/**
 * Map views: the simulation grid drawn on a real city (display only - the
 * simulation and its coordinates are untouched).
 *
 * A view (docs/lab/maps/<name>.json, generated by
 * ridehail-toronto/bin/toronto_map_warp.py) is a lookup table, the
 * "lattice", from display grid coordinates to map coordinates in km, plus
 * the city's ward outlines. Display grid coordinates are the model's, rolled
 * north-south so the city core sits on the bottom edge (Toronto's lakeshore):
 * the torus is cut open at the display edges, which become the city
 * boundary. The lattice spans -0.5 .. size - 0.5 on both axes, as the plain
 * map's scales do, so it applies to any city size.
 *
 * map.js keeps all its logic (edge wraps, glides, headings) in display grid
 * units and converts points to km only where it hands them to Chart.js; the
 * roads, core, wards and heatmap cells are drawn here.
 *
 * The page loads the views itself (loadMapViews, at start-up: they are web
 * assets, not part of the Python package); the real-city presets arrive once,
 * with the "Pyodide loaded" message (worker.py get_city_presets).
 */
import { CITY_CORE_FRACTION } from "../js/constants.js";
import { resolvedTheme, themeColor } from "../js/theme.js";

const VIEW_FORMAT = 1;
// Space around the city's bounding box, in km
const MARGIN_KM = 0.5;
// Points per block along the drawn roads, routes and heatmap cells
const SAMPLES_PER_BLOCK = 4;
const STORAGE_KEY = "labMapView";

// Where the views are, relative to the page
const MAP_VIEW_DIR = "maps";

const _viewTexts = new Map(); // name -> JSON text, as fetched
const _views = new Map(); // name -> parsed view
const _cityPresets = new Map(); // name -> {title, scale, mapView, settings}

/**
 * Fetch the named views (parsed when first used). A view that can't be
 * fetched is left out, with a warning: the map just doesn't offer it.
 * @param {string[]} names
 */
export async function loadMapViews(names) {
  await Promise.all(
    names.map(async (name) => {
      try {
        const response = await fetch(`${MAP_VIEW_DIR}/${name}.json`);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        _viewTexts.set(name, await response.text());
        _views.delete(name);
      } catch (error) {
        console.warn(`map view ${name}: not available`, error);
      }
    }),
  );
}

/** Store the real-city presets from worker.py get_city_presets. */
export function registerCityPresets(presets) {
  for (const [name, preset] of Object.entries(presets || {})) {
    _cityPresets.set(name, preset);
  }
}

/** The real-city presets as [{name, title}], in their order. */
export function listCityPresets() {
  return [..._cityPresets].map(([name, preset]) => ({ name, title: preset.title }));
}

/** A real-city preset, or undefined. */
export function getCityPreset(name) {
  return _cityPresets.get(name);
}

export function hasMapView(name) {
  return _viewTexts.has(name);
}

function _loadView(name) {
  if (_views.has(name)) return _views.get(name);
  const text = _viewTexts.get(name);
  if (!text) return null;
  try {
    const view = JSON.parse(text);
    if (view.format !== VIEW_FORMAT) {
      console.error(`map view ${name}: format ${view.format}, expected ${VIEW_FORMAT}`);
      return null;
    }
    _views.set(name, view);
    return view;
  } catch (error) {
    console.error(`map view ${name}: unreadable`, error);
    return null;
  }
}

/** The map view the viewer last chose, or null (a per-viewer convenience). */
export function loadSavedMapView() {
  try {
    return localStorage.getItem(STORAGE_KEY) || null;
  } catch {
    return null;
  }
}

export function saveMapView(name) {
  try {
    if (name) localStorage.setItem(STORAGE_KEY, name);
    else localStorage.removeItem(STORAGE_KEY);
  } catch {
    // Storage unavailable: the choice lasts for this page only
  }
}

/**
 * The core's lower bound on each axis, as City.core_bounds() computes it
 * (ridehail/atom.py) and map.js _updateCoreShading.
 */
function _coreLow(citySize) {
  const zone = Math.floor(citySize * CITY_CORE_FRACTION);
  return Math.floor((citySize - zone) / 2);
}

/**
 * A view fitted to a city size, or null if the view is unknown.
 * @returns {MapProjection|null}
 */
export function createProjection(name, citySize) {
  const view = name ? _loadView(name) : null;
  if (!view || !(citySize > 0)) return null;
  return new MapProjection(name, view, citySize);
}

class MapProjection {
  constructor(name, view, citySize) {
    this.name = name;
    this.view = view;
    this.citySize = citySize;
    // Lattice points per side; lattice point (row j, column i) is at
    // lattice[2 * (j * n + i)], [... + 1]
    this.n = view.city_size * view.resolution + 1;
    this.lattice = Float64Array.from(view.lattice);
    this.rollY = _coreLow(citySize);
    const [width, height] = view.size;
    this.bounds = {
      xMin: -MARGIN_KM,
      xMax: width + MARGIN_KM,
      yMin: -MARGIN_KM,
      yMax: height + MARGIN_KM,
    };
    this.aspect = (width + 2 * MARGIN_KM) / (height + 2 * MARGIN_KM);
    this.key = `${name}:${citySize}`;
    this._roads = null;
    this._cells = new Map();
  }

  /**
   * Model coordinates -> display grid coordinates. A point on a seam
   * (half a block beyond an edge, as an interpolated frame puts a car that is
   * crossing it) belongs to the edge the car is heading for: the bottom or
   * left edge if it is moving south or west, the top or right edge otherwise.
   * map.js then wraps it to the far edge exactly as on the plain map.
   * @param {string} [direction] - "NORTH" | "EAST" | "SOUTH" | "WEST"
   */
  toDisplay(x, y, direction) {
    return {
      x: this._wrap(x, direction === "WEST"),
      y: this._wrap(y - this.rollY, direction === "SOUTH"),
    };
  }

  _wrap(value, towardsLow) {
    const size = this.citySize;
    let d = ((value % size) + size) % size;
    if (towardsLow && d >= size - 0.5) d -= size;
    return d;
  }

  /** Display grid coordinates -> map coordinates (km), {x, y}. */
  toMap(xd, yd) {
    const cells = this.n - 1;
    const scale = cells / this.citySize;
    const fx = Math.min(Math.max((xd + 0.5) * scale, 0), cells);
    const fy = Math.min(Math.max((yd + 0.5) * scale, 0), cells);
    const i = Math.min(Math.floor(fx), cells - 1);
    const j = Math.min(Math.floor(fy), cells - 1);
    const tx = fx - i;
    const ty = fy - j;
    const L = this.lattice;
    const k00 = 2 * (j * this.n + i);
    const k10 = k00 + 2;
    const k01 = k00 + 2 * this.n;
    const k11 = k01 + 2;
    const w00 = (1 - tx) * (1 - ty);
    const w10 = tx * (1 - ty);
    const w01 = (1 - tx) * ty;
    const w11 = tx * ty;
    return {
      x: L[k00] * w00 + L[k10] * w10 + L[k01] * w01 + L[k11] * w11,
      y: L[k00 + 1] * w00 + L[k10 + 1] * w10 + L[k01 + 1] * w01 + L[k11 + 1] * w11,
    };
  }

  /** Model [x, y] -> map coordinates (km). */
  modelToMap(point) {
    const d = this.toDisplay(point[0], point[1]);
    return this.toMap(d.x, d.y);
  }

  /**
   * A grid heading (degrees clockwise from north, as map.js rotates cars:
   * 0, 90, 180, 270) turned to follow the warped road at a display point.
   * The map's km scales are equal on both axes, so the angle carries over
   * to pixels.
   */
  headingAt(xd, yd, gridRotation) {
    const radians = (gridRotation * Math.PI) / 180;
    const dx = Math.round(Math.sin(radians));
    const dy = Math.round(Math.cos(radians));
    const step = 0.25;
    const a = this.toMap(xd - dx * step, yd - dy * step);
    const b = this.toMap(xd + dx * step, yd + dy * step);
    const ex = b.x - a.x;
    const ey = b.y - a.y;
    if (Math.abs(ex) + Math.abs(ey) < 1e-9) return gridRotation;
    const degrees = (Math.atan2(ex, ey) * 180) / Math.PI;
    return (degrees + 360) % 360;
  }

  /** The roads (integer grid lines) as polylines of map points, cached. */
  roads() {
    if (this._roads) return this._roads;
    const size = this.citySize;
    const count = size * SAMPLES_PER_BLOCK + 1;
    const ts = Array.from({ length: count }, (_, k) => -0.5 + k / SAMPLES_PER_BLOCK);
    this._roads = [];
    for (let c = 0; c < size; c++) {
      this._roads.push(ts.map((t) => this.toMap(c, t)));
      this._roads.push(ts.map((t) => this.toMap(t, c)));
    }
    return this._roads;
  }

  /**
   * The outline of the display grid rectangle [x0, x1] x [y0, y1], as a
   * closed polygon of map points (cached by its corners).
   */
  cellPolygon(x0, x1, y0, y1) {
    const key = `${x0},${x1},${y0},${y1}`;
    let polygon = this._cells.get(key);
    if (polygon) return polygon;
    polygon = [];
    const side = (ax, ay, bx, by) => {
      const steps = Math.max(1, Math.ceil(Math.max(Math.abs(bx - ax), Math.abs(by - ay)) * 2));
      for (let k = 0; k < steps; k++) {
        const t = k / steps;
        polygon.push(this.toMap(ax + (bx - ax) * t, ay + (by - ay) * t));
      }
    };
    side(x0, y0, x1, y0);
    side(x1, y0, x1, y1);
    side(x1, y1, x0, y1);
    side(x0, y1, x0, y0);
    this._cells.set(key, polygon);
    return polygon;
  }

  /** The city core (map.js _coreShading {low, high}) as a polygon. */
  corePolygon(core) {
    // Display rows: the core's model rows low .. high-1 roll to 0 .. high-low-1
    const top = core.high - core.low - 0.5;
    return this.cellPolygon(core.low - 0.5, core.high - 0.5, -0.5, top);
  }

  /**
   * The torus-shortest straight route from model point a to model point b
   * (as the plain map's overlay draws it), as polylines of map points,
   * broken where the route crosses a display edge.
   */
  route(a, b) {
    const size = this.citySize;
    const d = [0, 1].map((i) => {
      let v = b[i] - a[i];
      if (v > size / 2) v -= size;
      if (v < -size / 2) v += size;
      return v;
    });
    const steps = Math.max(1, Math.ceil((Math.abs(d[0]) + Math.abs(d[1])) * SAMPLES_PER_BLOCK));
    const lines = [];
    let line = [];
    let previous = null;
    for (let k = 0; k <= steps; k++) {
      const t = k / steps;
      const p = this.toDisplay(a[0] + d[0] * t, a[1] + d[1] * t);
      if (
        previous &&
        (Math.abs(p.x - previous.x) > size / 2 || Math.abs(p.y - previous.y) > size / 2)
      ) {
        lines.push(line);
        line = [];
      }
      line.push(this.toMap(p.x, p.y));
      previous = p;
    }
    lines.push(line);
    return lines.filter((l) => l.length > 1);
  }
}

// ── Drawing ─────────────────────────────────────────────────────────────────

function _pixelMapper(chart) {
  const { x, y } = chart.scales;
  return (p) => [x.getPixelForValue(p.x), y.getPixelForValue(p.y)];
}

function _tracePolygon(ctx, points, toPixel) {
  points.forEach((p, k) => {
    const [px, py] = toPixel(p);
    if (k === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  });
  ctx.closePath();
}

function _tracePolyline(ctx, points, toPixel) {
  points.forEach((p, k) => {
    const [px, py] = toPixel(p);
    if (k === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  });
}

/**
 * Fill heatmap cells: cells is an iterable of [x0, x1, y0, y1, color] in
 * display grid coordinates.
 */
export function fillViewCells(chart, projection, cells) {
  const ctx = chart.ctx;
  const toPixel = _pixelMapper(chart);
  ctx.save();
  for (const [x0, x1, y0, y1, color] of cells) {
    ctx.fillStyle = color;
    ctx.beginPath();
    _tracePolygon(ctx, projection.cellPolygon(x0, x1, y0, y1), toPixel);
    ctx.fill();
  }
  ctx.restore();
}

/**
 * Stroke a route (MapProjection.route) on the chart, in the context's
 * current stroke style.
 */
export function strokeViewRoute(chart, projection, a, b) {
  const ctx = chart.ctx;
  const toPixel = _pixelMapper(chart);
  for (const line of projection.route(a, b)) {
    ctx.beginPath();
    _tracePolyline(ctx, line, toPixel);
    ctx.stroke();
  }
}

/**
 * The map behind the vehicles: beyond the city, the wards, the core and the
 * roads. Static between frames, so it is drawn once into an offscreen
 * canvas and redrawn only when the size, theme, core or road width changes.
 * @param {function} getState - returns {projection, core, roadWidth}; the
 *   plugin draws nothing while projection is null
 */
export function createMapViewPlugin(getState) {
  let cache = { key: null, canvas: null };
  return {
    id: "mapView",
    beforeDraw(chart) {
      const state = getState();
      const projection = state?.projection;
      if (!projection || !chart.chartArea) return;
      const ratio = chart.currentDevicePixelRatio || 1;
      const core = state.core;
      const key = [
        projection.key,
        chart.width,
        chart.height,
        ratio,
        resolvedTheme(),
        core ? `${core.low}-${core.high}` : "none",
        state.roadWidth,
      ].join("|");
      if (cache.key !== key) {
        cache = { key, canvas: _drawLayer(chart, projection, state, ratio) };
      }
      chart.ctx.drawImage(cache.canvas, 0, 0, chart.width, chart.height);
    },
  };
}

function _drawLayer(chart, projection, state, ratio) {
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(chart.width * ratio));
  canvas.height = Math.max(1, Math.round(chart.height * ratio));
  const ctx = canvas.getContext("2d");
  ctx.scale(ratio, ratio);
  const toPixel = _pixelMapper(chart);
  const area = chart.chartArea;
  const view = projection.view;
  const toPoint = ([x, y]) => ({ x, y });

  // Beyond the city (the lake, the neighbouring municipalities)
  ctx.fillStyle = themeColor("MAP_OUTSIDE");
  ctx.fillRect(area.left, area.top, area.right - area.left, area.bottom - area.top);
  // The city: the wards' own outlines, which include the islands and spits
  // that the roads leave out
  ctx.fillStyle = themeColor("LAND");
  ctx.beginPath();
  for (const ward of view.wards) {
    for (const ring of ward.rings) _tracePolygon(ctx, ring.map(toPoint), toPixel);
  }
  ctx.fill();
  if (state.core) {
    ctx.fillStyle = themeColor("CORE");
    ctx.beginPath();
    _tracePolygon(ctx, projection.corePolygon(state.core), toPixel);
    ctx.fill();
  }
  ctx.lineJoin = "round";
  ctx.lineCap = "round";
  ctx.strokeStyle = themeColor("ROAD");
  ctx.lineWidth = state.roadWidth;
  ctx.beginPath();
  for (const road of projection.roads()) _tracePolyline(ctx, road, toPixel);
  ctx.stroke();
  ctx.strokeStyle = themeColor("MAP_WARD_LINE");
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (const ward of view.wards) {
    for (const ring of ward.rings) _tracePolygon(ctx, ring.map(toPoint), toPixel);
  }
  ctx.stroke();
  return canvas;
}
